<?php require 'app/init.php';require 'app/view.php';$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT p.*,u.nombre,u.usuario FROM publicaciones p JOIN usuarios u ON u.id=p.usuario_id WHERE p.id=?');$s->execute([$id]);$p=$s->fetch();if(!$p){http_response_code(404);exit('Publicación no encontrada');}top('Publicación');?><main class="card" style="max-width:800px;margin:30px auto"><a href="index.php">← Volver</a><h2><?=e($p['titulo']?:'Publicación')?></h2><p class="muted"><?=e($p['nombre'])?> · <?=e($p['creado_en'])?></p><p class="post-body"><?=e($p['contenido'])?></p><?php if($p['imagen']):?><img class="post-img" src="<?=e($p['imagen'])?>"><?php endif;?><h3>Comentarios</h3><?php $c=db()->prepare('SELECT c.*,u.nombre FROM comentarios c JOIN usuarios u ON u.id=c.usuario_id WHERE c.publicacion_id=? ORDER BY c.creado_en');$c->execute([$id]);foreach($c as $v):?><div class="comment"><strong><?=e($v['nombre'])?></strong> <span class="muted"><?=e($v['creado_en'])?></span><p><?=e($v['contenido'])?></p></div><?php endforeach;?><?php if(me()):?><form action="accion.php" method="post"><input type="hidden" name="csrf" value="<?=token()?>"><input type="hidden" name="id" value="<?=$id?>"><textarea name="contenido" maxlength="2000" required placeholder="Escribe un comentario..."></textarea><button name="accion" value="comentar">Comentar</button></form><?php else:?><a href="login.php">Inicia sesión para comentar</a><?php endif;?></main><?php bottom();?>